class Solution:
    def bestCoordinate(self, towers, radius):
        best_q=-1; best=[0,0]; r2=radius*radius
        for x in range(51):
            for y in range(51):
                q=0
                for tx,ty,tq in towers:
                    dx=tx-x; dy=ty-y; d2=dx*dx+dy*dy
                    if d2<=r2:
                        q += math.floor(tq/(1+math.sqrt(d2)))
                if q>best_q:
                    best_q=q; best=[x,y]
        return best

