#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>

typedef struct { char* s; int pos; int len; } Tok;
static void skipWS(Tok* t) {
    while (t->pos < t->len && (t->s[t->pos]==' ' || t->s[t->pos]==',' || t->s[t->pos]=='\t' || t->s[t->pos]=='\n' || t->s[t->pos]=='\r')) t->pos++;
}
static char* nextToken(Tok* t) {
    skipWS(t); if (t->pos >= t->len) return NULL;
    int start=t->pos;
    if (t->s[t->pos]=='[') {
        int depth=0;
        while (t->pos<t->len) { char c=t->s[t->pos++]; if(c=='[')depth++; else if(c==']'){depth--; if(depth==0)break;} }
    } else if (t->s[t->pos]=='"') {
        t->pos++;
        while(t->pos<t->len && t->s[t->pos]!='"') t->pos++;
        if(t->pos<t->len) t->pos++;
    } else {
        while(t->pos<t->len && t->s[t->pos]!=',' && t->s[t->pos]!=']' && t->s[t->pos]!='[') t->pos++;
    }
    int n=t->pos-start; char* tok=(char*)malloc(n+1); memcpy(tok,t->s+start,n); tok[n]='\0';
    int k=n-1; while(k>=0 && (tok[k]==' '||tok[k]=='\t'||tok[k]=='\n'||tok[k]=='\r')) tok[k--]='\0';
    return tok;
}
static int parse_int(Tok* t){ char* tok=nextToken(t); int v=atoi(tok); free(tok); return v; }
static int* parse_int_array(Tok* t,int* out_size){
    char* tok=nextToken(t);
    if(!tok || strcmp(tok,"[]")==0){ if(tok)free(tok); *out_size=0; return NULL; }
    int len=(int)strlen(tok); char* inner=(char*)malloc(len-1); memcpy(inner,tok+1,len-2); inner[len-2]='\0'; free(tok);
    int size=1; for(int i=0;inner[i];i++) if(inner[i]==',') size++;
    int* arr=(int*)malloc(size*sizeof(int)); Tok t2={inner,0,(int)strlen(inner)};
    for(int i=0;i<size;i++) arr[i]=parse_int(&t2);
    free(inner); *out_size=size; return arr;
}
static int** parse_int_2d(Tok* t,int* out_rows,int** out_cols){
    char* tok=nextToken(t);
    if(!tok || strcmp(tok,"[]")==0){ if(tok)free(tok); *out_rows=0; *out_cols=NULL; return NULL; }
    int len=(int)strlen(tok); char* inner=(char*)malloc(len-1); memcpy(inner,tok+1,len-2); inner[len-2]='\0'; free(tok);
    int rows=0,depth=0; for(int i=0;inner[i];i++){ if(inner[i]=='['){ if(depth==0)rows++; depth++; } else if(inner[i]==']')depth--; }
    int** mat=(int**)malloc(rows*sizeof(int*)); int* cols=(int*)malloc(rows*sizeof(int));
    Tok t2={inner,0,(int)strlen(inner)}; for(int i=0;i<rows;i++) mat[i]=parse_int_array(&t2,&cols[i]);
    free(inner); *out_rows=rows; *out_cols=cols; return mat;
}

int* bestCoordinate(int** towers,int towersSize,int* towersColSize,int radius,int* returnSize){
    (void)towersColSize;
    int* ans=(int*)malloc(2*sizeof(int)); ans[0]=0; ans[1]=0; *returnSize=2;
    int best=-1, r2=radius*radius;
    for(int x=0;x<=50;x++) for(int y=0;y<=50;y++){
        int total=0;
        for(int i=0;i<towersSize;i++){
            int dx=towers[i][0]-x, dy=towers[i][1]-y, d2=dx*dx+dy*dy;
